    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint x) public payable {
        require(true);
        uint initial = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        uint again = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        assert(initial == 0 && again == initial && address(c).balance >= 0 && x >= 0);
    }
    receive() external payable {}
