pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 x) internal {
        vm.assume(true);
        uint256 initial;
        try c.pastBlockTime() returns (uint256 __r) { initial = __r; } catch { return; }
        uint256 again;
        try c.pastBlockTime() returns (uint256 __r) { again = __r; } catch { return; }
        assertTrue(initial == 0 && again == initial && address(c).balance >= 0 && x >= 0);
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
